# Sample size for a +/- margin on accuracy (95% confidence)
import math, random

def needed(p, margin, z=1.96):
    return math.ceil(z * z * p * (1 - p) / margin ** 2)

for p in (0.5, 0.9):
    for margin in (0.05, 0.02, 0.01):
        print("accuracy~%.1f margin +/-%.2f -> n = %d" % (p, margin, needed(p, margin)))

# Check by simulation: true accuracy 0.9, n = 865
random.seed(5)
n, trials, covered = 865, 2000, 0
for _ in range(trials):
    acc = sum(random.random() < 0.9 for _ in range(n)) / n
    if abs(acc - 0.9) <= 0.02:
        covered += 1
print("n=865: estimate within 2 points in %.1f%% of runs" % (100 * covered / trials))
